const css = "body{font-family:system-ui;color:#222}";
const etag = '"v7-harga"';

function server(req) {
  if (req.url === "/app.3f9a1c.css")
    return { status: 200, headers: { "cache-control": "public, max-age=31536000, immutable" }, body: css };
  if (req.url === "/api/harga") {
    if (req.headers["if-none-match"] === etag) return { status: 304, headers: { etag }, body: "" };
    return { status: 200, headers: { etag, "cache-control": "no-cache" }, body: JSON.stringify({ kopi: 45000 }) };
  }
  return { status: 404, headers: {}, body: "tidak ditemukan" };
}

const permintaan = [
  { url: "/app.3f9a1c.css", headers: {} },
  { url: "/api/harga", headers: {} },
  { url: "/api/harga", headers: { "if-none-match": etag } },
  { url: "/tidak-ada", headers: {} },
];
for (const req of permintaan) {
  const r = server(req);
  const isi = r.status === 304 ? "(tanpa body)" : r.body.slice(0, 24);
  console.log(String(r.status).padEnd(4), req.url.padEnd(16), (r.headers["cache-control"] ?? "-").padEnd(36), isi);
}

