function throttle(fn, ms, jam) {
  let terakhir = -Infinity;
  return (...args) => {
    if (jam() - terakhir >= ms) {
      terakhir = jam();
      fn(...args);
    }
  };
}
let sekarang = 0;
const simpanPosisi = throttle((y) => console.log(`t=${sekarang}ms simpan posisi ${y}`), 100, () => sekarang);
for (let t = 0; t <= 300; t += 25) {     // event scroll setiap 25 ms
  sekarang = t;
  simpanPosisi(t * 2);
}

